const post_body=(e,t,a,n,s,o)=>`<div class="col-lg-4 col-md-6 col-sm-6 col-12 post mb-5" data-aos="fade-up" data-aos-delay="${100*e}">\n            <div class="media media-custom d-block mb-4 h-100">\n              <a data-post-id="${t}" class="mb-4 d-block post-link"><img src="../images/${o}" alt="" class="img-fluid"></a>\n              <div class="media-body">\n                <span class="meta-post">${a}</span>\n                <h2 class="mt-0 mb-3"><a data-post-id="${t}" class="post-link">${n}</a></h2>\n                <p>${s}</p>\n              </div>\n            </div>\n          </div>`;let current_page=1;const posts_per_page=6;let loaded=!1;function page_indicator_builder(e,t){let a=Math.ceil(e/t),n=document.getElementById("page_indicator");for(let e=1;e<=a;e++){let a=document.createElement("li");a.setAttribute("page-number",e.toString()),a.id="page-indicator-number-"+e,a.addEventListener("click",function(e){let a=this.getAttribute("page-number"),n=parseInt(a);n!==current_page&&(load_posts((n-1)*t,t),document.getElementById("page-indicator-number-"+current_page).classList.remove("active"),this.classList.add("active"),current_page=n)});let s=document.createElement("a");s.href="#next",s.classList.add("smoothscroll"),s.innerText=e.toString(),a.appendChild(s),n.appendChild(a)}document.getElementById("page-indicator-number-1").classList.add("active")}function load_posts(e,t){const a=window.location.pathname.includes("/bg");fetch(`../locales/${a?"bg":"en"}.json`).then(e=>e.json()).then(a=>{let n=a.posts,s=n.length;t=s<t+e?s-e:t,loaded||(page_indicator_builder(s,6),loaded=!0);let o=document.getElementById("posts-container");o.innerHTML="";let d=1;for(let a=e;a<e+t;a++){let e=n[a];o.innerHTML+=post_body(d>3?d-3:d,e.id,e.tag,e.title,e.summarize,e.main_image),++d}document.querySelectorAll(".post-link").forEach(e=>{e.addEventListener("click",()=>{let t=e.getAttribute("data-post-id");window.open("post.html?name="+n[parseInt(t)-1].title.toLowerCase(),"_self")})})})}load_posts(0,6);